{"content": "from fastapi import FastAPI, APIRouter, routing
from fastapi.routing import _EffectiveRouteContext

def test_apirouter_iter_route_contexts():
    router = APIRouter()
    @router.get("/test")
    def test_endpoint():
        return {"hello": "world"}

    contexts = list(router.iter_route_contexts())
    assert len(contexts) == 1
    assert isinstance(contexts[0], _EffectiveRouteContext)
    assert contexts[0].path == "/test"

def test_fastapi_iter_route_contexts():
    app = FastAPI()
    @app.get("/test")
    def test_endpoint():
        return {"hello": "world"}

    contexts = list(app.iter_route_contexts())
    assert len(contexts) == 1
    assert isinstance(contexts[0], _EffectiveRouteContext)
    assert contexts[0].path == "/test"

def test_nested_routers():
    app = FastAPI()
    sub_router = APIRouter()
    @sub_router.get("/sub")
    def sub_endpoint():
        return {"hello": "sub"}

    app.include_router(sub_router, prefix="/prefix")

    contexts = list(app.iter_route_contexts())
    assert len(contexts) == 1
    assert contexts[0].path == "/prefix/sub"

if __name__ == "__main__":
    try:
        test_apirouter_iter_route_contexts()
        print("test_apirouter_iter_route_contexts passed")
        test_fastapi_iter_route_contexts()
        print("test_fastapi_iter_route_contexts passed")
        test_nested_routers()
        print("test_nested_routers passed")
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
